{
    (void)arg;
    int count;
    chRegSetThreadName("blink");
    while (1) {
      systime_t time = 100;
      chThdSleepMilliseconds(time);

      calc_stat();      
      measure_power_dbm();
      disp_update_power();

      if (++count == 10) {
        stat.fps = stat.fps_count;
        stat.fps_count = 0;
        stat.overflow = stat.overflow_count;
        stat.overflow_count = 0;
        count = 0;

        measure_adc();
        disp_update();
      }
    }
}

